using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.Linq;using System.Reflection;
public static class CymbalReachCandidate{public static void Run(){EditorSceneManager.OpenScene("Assets/MusicRoom.unity");var seq=Object.FindFirstObjectByType<PerformanceSequence>();var seat=(Transform)seq.GetType().GetField("drumSeatTarget",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(seq);var cym=Object.FindObjectsByType<DrumSound>(FindObjectsSortMode.None).First(d=>d.name=="CymbalHitZone");var original=cym.GetComponent<Collider>();Vector3 dir=Vector3.ProjectOnPlane(seat.position-cym.transform.position,Vector3.up).normalized;
var go=new GameObject("Cymbal reach candidate");go.transform.SetPositionAndRotation(cym.transform.position+dir*.27f+Vector3.right*.08f+Vector3.down*.04f,Quaternion.LookRotation(dir,Vector3.up));var box=go.AddComponent<BoxCollider>();box.isTrigger=true;box.size=new Vector3(.20f,.16f,.56f);Physics.SyncTransforms();
Debug.Log("CANDIDATE distance="+Vector3.Distance(seat.position,box.ClosestPoint(seat.position))+" old="+Vector3.Distance(seat.position,original.ClosestPoint(seat.position))+" center="+go.transform.position+" normal="+dir);bool valid=true;
foreach(var d in Object.FindObjectsByType<DrumSound>(FindObjectsSortMode.None)){var c=d.GetComponent<Collider>();if(c==null||c==original)continue;bool overlap=Physics.ComputePenetration(box,go.transform.position,go.transform.rotation,c,c.transform.position,c.transform.rotation,out _,out _);Debug.Log("CANDIDATE other="+d.name+" overlap="+overlap);if(overlap)valid=false;}

var hullVertices=original.GetComponent<MeshCollider>().sharedMesh.vertices.ToList();
for(int x=-1;x<=1;x+=2)for(int y=-1;y<=1;y+=2)for(int z=-1;z<=1;z+=2)hullVertices.Add(cym.transform.InverseTransformPoint(go.transform.TransformPoint(Vector3.Scale(box.size*.5f,new Vector3(x,y,z)))));
var mesh=new Mesh();mesh.name="Cymbal player-facing contact tolerance";mesh.vertices=hullVertices.ToArray();int offset=hullVertices.Count-8;
int[] faces={0,1,3,0,3,2,4,6,7,4,7,5,0,4,5,0,5,1,2,3,7,2,7,6,0,2,6,0,6,4,1,5,7,1,7,3};
mesh.triangles=original.GetComponent<MeshCollider>().sharedMesh.triangles.Concat(faces.Select(i=>i+offset)).ToArray();mesh.RecalculateBounds();
original.GetComponent<MeshCollider>().sharedMesh=mesh;Physics.BakeMesh(mesh.GetInstanceID(),true);Object.DestroyImmediate(go);Physics.SyncTransforms();
Debug.Log("TOLERANCE new reach="+Vector3.Distance(seat.position,original.ClosestPoint(seat.position)));
foreach(var d in Object.FindObjectsByType<DrumSound>(FindObjectsSortMode.None)){var c=d.GetComponent<Collider>();if(c==null||c==original)continue;bool overlap=Physics.ComputePenetration(original,original.transform.position,original.transform.rotation,c,c.transform.position,c.transform.rotation,out _,out _);Debug.Log("TOLERANCE other="+d.name+" overlap="+overlap);if(overlap)valid=false;
// Inflate neighboring boxes by a tip diameter. Disjoint inflated zones guarantee that one
// 12 mm spherical tip cannot simultaneously overlap this surface and the neighboring drum.
if(c is BoxCollider otherBox){Vector3 oldSize=otherBox.size;Vector3 scale=otherBox.transform.lossyScale;otherBox.size+=new Vector3(.048f/Mathf.Abs(scale.x),.048f/Mathf.Abs(scale.y),.048f/Mathf.Abs(scale.z));Physics.SyncTransforms();bool nearby=Physics.ComputePenetration(original,original.transform.position,original.transform.rotation,c,c.transform.position,c.transform.rotation,out _,out _);otherBox.size=oldSize;Physics.SyncTransforms();Debug.Log("TOLERANCE 24mm clearance "+d.name+" safe="+!nearby);if(nearby)valid=false;}}
if(!valid)throw new System.Exception("Reach hull interferes with another drum");
var existing=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Physics/CymbalReachContactMesh.asset");
if(existing!=null){EditorUtility.CopySerialized(mesh,existing);original.GetComponent<MeshCollider>().sharedMesh=existing;EditorUtility.SetDirty(existing);}else AssetDatabase.CreateAsset(mesh,"Assets/Physics/CymbalReachContactMesh.asset");AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/CymbalReachCandidate.unity");Debug.Log("TOLERANCE VALID");EditorApplication.Exit(0);}}
